def _valid_topo(graph, order):
    n = len(graph)
    if len(order) != n or sorted(order) != list(range(n)):
        return False
    pos = {v: i for i, v in enumerate(order)}
    for u in range(n):
        for v in graph[u]:
            if not pos[u] < pos[v]:
                return False
    return True
